$('discover').onclick=run(async()=>{setText('scanStatus','Scanning…');await commitInputs();const {found}=await api('scan',{prefix:$('prefix').value.trim()});$('found').replaceChildren();setText('scanStatus',found.length?'Click a device to add it, then Check & save.':'No tubes found. Enter their IPs manually.');for(const d of found){const b=document.createElement('button');b.textContent=d.name+' · '+d.ip;b.onclick=()=>{const tubes=readInputs();if(tubes.some(t=>t.ip===d.ip))return;const t=tubes.find(t=>!t.ip);if(!t){notice('All five slots are assigned.');return;}t.ip=d.ip;t.count=Math.min(1500,d.count);config.tubes=tubes;tubeInputs();b.disabled=true;};$('found').append(b);}});
for(const b of document.querySelectorAll('[data-test]'))b.onclick=run(async()=>{await commitInputs();await api('identify',{id:+$('testTube').value,color:b.dataset.test});notice('Color test finished. If the primary color was wrong, adjust color order in WLED.');});
function refreshNames(){for(const id of ['microphone','selectedTube','testTube']){const value=$(id).value;$(id).replaceChildren();for(const t of config.tubes)$(id).add(new Option(t.name,t.id));$(id).value=id==='microphone'?config.microphone:value||0;}}
let colorIndex=0;const wheel=$('colorWheel'),wheelContext=wheel.getContext('2d');
function hsv(h,s,v=1){const f=n=>{const k=(n+h*6)%6;return Math.round(255*v*(1-s*Math.max(0,Math.min(k,4-k,1))));};return [f(5),f(3),f(1)];}
function colorSet(hex){if(!/^#[\da-f]{6}$/i.test(hex))return;current().colors[colorIndex]=hex.toLowerCase();$('hex').value=hex;['red','green','blue'].forEach((id,i)=>$(id).value=parseInt(hex.slice(1+i*2,3+i*2),16));$('colorPreview').style.background=hex;mark();populate();}
function openColor(i){colorIndex=i;const hex=current().colors[i];$('hex').value=hex;['red','green','blue'].forEach((id,j)=>$(id).value=parseInt(hex.slice(1+j*2,3+j*2),16));$('colorPreview').style.background=hex;$('moveColorLeft').disabled=i===0;$('moveColorRight').disabled=i>=current().colors.length-1;$('removeColor').disabled=current().colors.length===1;$('colorDialog').showModal();}
function wheelPick(e){const r=wheel.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*230-115,y=(e.clientY-r.top)/r.height*230-115;const c=hsv((Math.atan2(y,x)/(Math.PI*2)+1)%1,clamp(Math.hypot(x,y)/114));colorSet('#'+c.map(v=>v.toString(16).padStart(2,'0')).join(''));}
let wheelDrag=false;wheel.addEventListener('pointerdown',e=>{wheelDrag=true;wheel.setPointerCapture(e.pointerId);wheelPick(e);});wheel.addEventListener('pointermove',e=>{if(wheelDrag)wheelPick(e);});for(const ev of ['pointerup','pointercancel'])wheel.addEventListener(ev,()=>wheelDrag=false);
$('hex').onchange=()=>{if(!/^#[\da-f]{6}$/i.test($('hex').value)){notice('Use six hex digits, e.g. #38bdf8.');return;}colorSet($('hex').value);};for(const id of ['red','green','blue'])$(id).oninput=()=>colorSet('#'+['red','green','blue'].map(k=>Math.round(clamp($(k).value,0,255)).toString(16).padStart(2,'0')).join(''));
$('addColor').onclick=()=>{if(current().colors.length>=effect().colors)current().colors=current().colors.slice(0,effect().colors-1);current().colors.push('#ffffff');mark();populate();openColor(current().colors.length-1);};
$('doneColor').onclick=()=>$('colorDialog').close();$('removeColor').onclick=()=>{if(current().colors.length>1){current().colors.splice(colorIndex,1);mark();populate();$('colorDialog').close();}};
for(const [id,delta]of [['moveColorLeft',-1],['moveColorRight',1]])$(id).onclick=()=>{const colors=current().colors,next=colorIndex+delta;if(next<0||next>=colors.length)return;[colors[colorIndex],colors[next]]=[colors[next],colors[colorIndex]];mark();populate();colorIndex=next;$('colorDialog').close();openColor(next);};
function initWheel(){const data=wheelContext.createImageData(230,230);for(let y=0;y<230;y++)for(let x=0;x<230;x++){const dx=x-115,dy=y-115,s=Math.hypot(dx,dy)/114;if(s>1)continue;const c=hsv((Math.atan2(dy,dx)/(2*Math.PI)+1)%1,s),i=(y*230+x)*4;data.data.set([...c,255],i);}wheelContext.putImageData(data,0,0);for(const [name,hex]of [['Red','#ff0000'],['Orange','#ff8000'],['Yellow','#ffff00'],['Green','#00ff00'],['Cyan','#00ffff'],['Blue','#0000ff'],['Purple','#8000ff'],['Pink','#ff0080'],['White','#ffffff'],['Black','#000000']]){const b=document.createElement('button');b.style.background=hex;b.title=name;b.setAttribute('aria-label',name);b.onclick=()=>colorSet(hex);$('swatches').append(b);}}
function download(name,text){const u=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
$('export').onclick=run(async()=>{if(layoutDirty)await saveLayout();await flush();download('TubeRoom-setup.json',JSON.stringify(config,null,2));});$('import').onclick=()=>{if(status.live){notice('Stop first.');return;}$('importFile').click();};$('importFile').onchange=run(async e=>{const f=e.target.files[0];if(!f)return;if(f.size>64000)throw Error('Setup file is too large.');config=(await api('config',JSON.parse(await f.text()))).config;dirty=false;layoutDirty=false;populate();refreshNames();notice('Setup imported. Check connections before starting.');});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&![...document.querySelectorAll('dialog')].some(d=>d.open))$('blackout').click();});
let updateBundle=null,updateBusy=false,installedPid=0;
function updateButtons(busy){updateBusy=busy;for(const id of ['checkUpdates','installUpdate','chooseUpdate','saveUpdateSource','rollbackUpdate'])$(id).disabled=busy;}
$('updatesBtn').onclick=run(async()=>{$('updates').showModal();const u=await api('update/status');setText('updateVersion','Installed: TubeRoom '+u.version);$('updateSource').value=u.source;$('rollbackUpdate').hidden=!u.canRollback;$('installUpdate').hidden=true;updateBundle=null;setText('updateNotes','');setText('updateMessage',u.notice||(!u.managed?'Reopen with Start-TubeRoom.command to enable updates.':u.source?'Ready to check for updates.':'Install an update file or save a trusted source.'));});
$('saveUpdateSource').onclick=run(async()=>{await api('update/source',{url:$('updateSource').value.trim()});updateBundle=null;$('installUpdate').hidden=true;setText('updateMessage','Source saved.');});
$('checkUpdates').onclick=run(async()=>{updateButtons(true);try{const u=await api('update/check');updateBundle=null;$('installUpdate').hidden=!u.available;setText('updateMessage',u.available?'TubeRoom '+u.version+' is ready.':'You have the latest version.');setText('updateNotes',u.notes||'');}finally{updateButtons(false);}});
$('chooseUpdate').onclick=()=>{if(!updateBusy)$('updateFile').click();};$('updateFile').onchange=run(async e=>{const f=e.target.files[0];if(!f)return;if(f.size>2*1024*1024)throw Error('Update is too large.');const b=JSON.parse(await f.text());if(b.format!=='tuberoom-update-v1'||!Array.isArray(b.files))throw Error('Choose a TubeRoom update JSON file.');updateBundle=b;$('installUpdate').hidden=false;setText('updateMessage','Ready to install '+b.version);setText('updateNotes',b.notes||'');e.target.value='';});
async function installOrRollback(route,data){if(status.live)throw Error('Stop & restore the lights first.');await flush();if(layoutDirty)await saveLayout();updateButtons(true);try{installedPid=(await(await fetch('/api/state')).json()).pid;await api(route,data);setText('updateMessage','Restarting…');for(let i=0;i<60;i++){await new Promise(r=>setTimeout(r,500));try{const s=await(await fetch('/api/state')).json();if(s.pid&&s.pid!==installedPid){window.location.reload();return;}}catch{}}throw Error('Reopen Start-TubeRoom.command, then refresh Safari.');}finally{updateButtons(false);}}
$('installUpdate').onclick=run(()=>installOrRollback('update/install',updateBundle?{bundle:updateBundle}:{}));$('rollbackUpdate').onclick=run(()=>installOrRollback('update/rollback',{}));
let previewBusy=false;
async function sample(){if(!config||!$('livePreview').checked||previewBusy||requestBusy||status.busy||document.hidden)return;previewBusy=true;try{status=(await api('preview')).status;draw();}catch{}finally{previewBusy=false;}}
$('livePreview').onchange=()=>{draw();sample();};
async function boot(){const s=await(await fetch('/api/state')).json();token=s.token;config=s.config;status=s.status;effects=s.effects;refreshNames();renderEffects();populate();renderStatus();selection();initWheel();$('prefix').value=s.networks[0]?.prefix||'192.168.1';if(s.needsRestore&&!s.status.live)notice('A previous session needs restoring. Click Stop & restore before starting.');setInterval(sample,500);setInterval(async()=>{if(requestBusy||previewBusy||document.hidden)return;try{const s=await(await fetch('/api/state')).json();status=s.status;renderStatus();draw();}catch{setText('connection','App disconnected · lights may still run');}},3000);}
